		/** 
		 * Tests creating a new ATM.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a ATM");

			StringBuilder msg = new StringBuilder( "-- Failed to create a ATM" );

			try {            
				ATM entity = ATMService.getATMInstance().createATM( generateNewEntity() );
				thePrimaryKey = entity.getATMId();
				LOGGER.info( "-- Successfully created a ATM with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a ATM. 
		 */
		public ATM testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created ATM" );

			ATM entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read ATM with primary key" );
			msg.append( thePrimaryKey );
			
			ATMFetchOneSummary fetchOneSummary = new ATMFetchOneSummary( thePrimaryKey );

			try {
				entity = ATMService.getATMInstance().getATM( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found ATM " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a ATM.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a ATM." );

			StringBuilder msg = new StringBuilder( "Failed to update a ATM : " );        
			ATM entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created ATM." );

				// for use later on...
				thePrimaryKey = entity.getATMId();

				ATMService proxy = ATMService.getATMInstance();            
				proxy.updateATM( entity );   

				LOGGER.info( "-- Successfully saved ATM - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a ATM.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created ATM." );

			try{
			    ATM entity = testRead(); 
				ATMService.getATMInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted ATM with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete ATM with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all ATMs.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of ATMs:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all ATM : " );        
			List<ATM> collection  = null;

			try {
				// call the static get method on the ATMService
				collection = ATMService.getATMInstance().getAllATM();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					ATM entity = null;            
					Iterator<ATM> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getATMId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

